/// Fixed-bit base word (variable fields zeroed).
pub fn encode_fixed(encoding_id: &str) -> Result<u32, EncodeError> {
    match fixed_word(encoding_id) {
        Some(w) => Ok(w),
        None => Err(EncodeError::UnknownEncoding(encoding_id.to_string())),
    }
}

/// Pack named variable fields onto the fixed base. Unknown names are errors.
pub fn encode_with_fields(encoding_id: &str, fields: &[(&str, u64)]) -> Result<u32, EncodeError> {
    let mut w = encode_fixed(encoding_id)?;
    let defs = fields_for(encoding_id);
    if defs.is_empty() {
        if fields.is_empty() {
            return Ok(w);
        }
        return Err(EncodeError::NoVariableFields(encoding_id.to_string()));
    }
    for &(name, val) in fields {
        let Some(d) = defs.iter().find(|d| d.0 == name).map(|d| d.1) else {
            return Err(EncodeError::UnknownField {
                encoding: encoding_id.to_string(),
                field: name.to_string(),
            });
        };
        let width = (d.end - d.start + 1) as u32;
        if width == 0 || width > 32 {
            continue;
        }
        let max = (1u64 << width) - 1;
        if val > max {
            return Err(EncodeError::Overflow {
                encoding: encoding_id.to_string(),
                field: name.to_string(),
                value: val,
                width,
            });
        }
        let mask = (max as u32) << d.start;
        let placed = (val as u32) << d.start;
        // Part of a named field can be pinned by the encoding (SMSTOP pins
        // CRm<0> = 0 while CRm<2:1> vary). Writing over it would emit a
        // different instruction, so reject the value instead.
        let pinned = mask & !d.free;
        if pinned != 0 && (placed & pinned) != (w & pinned) {
            return Err(EncodeError::PinnedBits {
                encoding: encoding_id.to_string(),
                field: name.to_string(),
                value: val,
                mask,
                free: d.free,
            });
        }
        w = (w & !d.free) | (placed & d.free);
    }
    Ok(w)
}

fn fixed_word(id: &str) -> Option<u32> {
    FIXED.binary_search_by(|e| e.0.cmp(id)).ok().map(|i| FIXED[i].1)
}

fn fields_for(id: &str) -> &'static [(&'static str, FieldLayout)] {
    match FIELDS.binary_search_by(|e| e.0.cmp(id)) {
        Ok(i) => FIELDS[i].1,
        Err(_) => &[],
    }
}

/// Instruction class for an encoding ID, if known.
pub fn encoding_class(id: &str) -> Option<&'static str> {
    ENCODING_CLASS
        .binary_search_by(|e| e.0.cmp(id))
        .ok()
        .map(|i| ENCODING_CLASS[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encode_fixed_unknown() {
        assert!(encode_fixed("NO_SUCH").is_err());
    }
}
